<script setup>
import { onMounted,reactive,ref } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import { api } from '../api.js';
import { currentUser } from '../auth.js';
import '../assets/groups.css';
const props=defineProps({id:String});const route=useRoute(),router=useRouter();
const board=ref(null),boards=ref([]),error=ref(''),busy=ref(false),weather=ref(null),comment=ref(''),slots=ref({});
const form=reactive({title:'Meet before the concert',startsAt:'',endsAt:''});
const place=reactive({label:'',latitude:1.3,longitude:103.85,sheltered:true});
const position=reactive({latitude:1.3,longitude:103.85,label:''});
const iso=ms=>new Date(ms).toISOString();
const time=ms=>new Date(ms).toLocaleString('en-SG',{dateStyle:'medium',timeStyle:'short'});
async function load(){if(props.id){const data=(await api.meetup(props.id)).meetup;board.value=data;
 slots.value=Object.fromEntries(data.grid.map(s=>{const own=data.availability.find(a=>a.starts_at<=s.startsAt&&a.ends_at>=s.startsAt+1800000);return[s.startsAt,{selected:Boolean(own),latitude:own?.latitude??null,longitude:own?.longitude??null,label:own?.label??''}];}));
 }else boards.value=(await api.meetups()).meetups;}
onMounted(async()=>{try{await load();}catch(e){error.value=e.message;}});
async function act(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn();await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function create(){await act(async()=>{const scope={};for(const k of ['partyId','connectionId','kakiConversationId'])if(typeof route.query[k]==='string')scope[k]=route.query[k];const r=await api.createMeetup({...form,...scope,startsAt:new Date(form.startsAt).toISOString(),endsAt:new Date(form.endsAt).toISOString()});await router.push(`/meetups/${r.meetup.id}`);window.location.reload();});}
async function saveAvailability(){await act(()=>api.meetupAvailability(props.id,Object.entries(slots.value).filter(([,s])=>s.selected).map(([start,s])=>({startsAt:iso(Number(start)),endsAt:iso(Number(start)+1800000),...(s.latitude!==null&&s.longitude!==null?{latitude:s.latitude,longitude:s.longitude,label:s.label}:{})}))));}
function assignLocation(){for(const slot of Object.values(slots.value))if(slot.selected)Object.assign(slot,{latitude:position.latitude,longitude:position.longitude,label:position.label});}
async function getWeather(){await act(async()=>{weather.value=(await api.meetupWeather(props.id)).weather;});}
</script>
<template><main class="container groups-page"><h1>{{board?.title??'Meetup planning'}}</h1><nav class="group-actions"><RouterLink to="/meetups">Your planning boards</RouterLink><RouterLink to="/groups/connect">Groups</RouterLink></nav><p v-if="error" class="group-error" role="alert">{{error}}</p><template v-if="!id"><p>Create a board from your group, accepted connection, or Kaki conversation so only its current participants can access it.</p><form v-if="route.query.partyId||route.query.connectionId||route.query.kakiConversationId" class="card group-panel" @submit.prevent="create"><label>Title<input v-model="form.title" maxlength="120" required></label><label>First possible meeting time<input v-model="form.startsAt" type="datetime-local" step="1800" required></label><label>End of availability window<input v-model="form.endsAt" type="datetime-local" step="1800" required></label><button class="btn btn--primary" :disabled="busy">Create planning board</button></form><RouterLink v-for="m in boards" :key="m.id" :to="`/meetups/${m.id}`">{{m.title}} · {{m.status}}</RouterLink></template><template v-else-if="board"><p>{{board.participantCount}} current participants · {{board.status}} · revision {{board.version}}</p><section class="card group-panel"><h2>When are you available?</h2><p>Select 30-minute slots. Only aggregate availability is shared; your submitted locations stay private.</p><div class="group-controls"><label v-for="s in board.grid" :key="s.startsAt" class="group-check"><input v-model="slots[s.startsAt].selected" type="checkbox">{{time(s.startsAt)}} · {{s.availableCount}}/{{board.participantCount}} available</label></div><div class="group-controls"><label>Location label<input v-model="position.label" placeholder="e.g. nearby MRT station"></label><label>Latitude<input v-model.number="position.latitude" type="number" min="-90" max="90" step="any"></label><label>Longitude<input v-model.number="position.longitude" type="number" min="-180" max="180" step="any"></label></div><button class="btn btn--ghost" @click="assignLocation">Apply this location to selected slots</button><p>You can assign a location, deselect those slots, then select other slots and assign another location. Location data is optional; approximate public starting points are sufficient.</p><button class="btn btn--primary" :disabled="busy" @click="saveAvailability">Save selected availability</button></section><form class="card group-panel" @submit.prevent="act(()=>api.proposeMeetupPlace(id,place))"><h2>Suggest an actual meeting place</h2><label>Place name<input v-model="place.label" required maxlength="150"></label><div class="group-controls"><label>Latitude<input v-model.number="place.latitude" type="number" min="-90" max="90" step="any" required></label><label>Longitude<input v-model.number="place.longitude" type="number" min="-180" max="180" step="any" required></label></div><label class="group-check"><input v-model="place.sheltered" type="checkbox">Sheltered place</label><button class="btn btn--primary" :disabled="busy">Add place</button></form><section class="card group-panel"><h2>Recommended options</h2><p>Ranked by attendance coverage, people within 15 km, total straight-line distance, then distance fairness and votes. These are not transit travel-time estimates.</p><article v-for="s in board.suggestions" :key="`${s.placeId}:${s.startsAt}`"><p>{{s.label}} · {{time(s.startsAt)}} · {{s.availableCount}}/{{s.participantCount}} available · {{s.totalDistanceKm}} km combined ({{s.locationRespondents}} locations supplied)</p><div class="group-actions"><button class="btn btn--ghost" :disabled="busy" @click="act(()=>api.voteMeetupPlace(id,s.placeId))">Vote for place</button><button class="btn btn--primary" :disabled="busy" @click="act(()=>api.proposeMeetupPlan(id,{placeId:s.placeId,startsAt:iso(s.startsAt),version:board.version}))">Propose this time &amp; place</button></div></article></section><section v-if="board.selected_place_id" class="card group-panel"><h2>Current proposal</h2><p>{{board.places.find(p=>p.id===board.selected_place_id)?.label}} · {{time(board.selected_start)}}</p><p>Approvals: {{board.approvals.length}}/{{board.requiredApprovers.length}}</p><button v-if="board.status==='proposed'&&board.requiredApprovers.includes(currentUser?.id)" class="btn btn--primary" :disabled="busy" @click="act(()=>api.approveMeetup(id,board.version))">Approve this revision</button><button class="btn btn--ghost" :disabled="busy" @click="getWeather">Check short-range weather</button><p v-if="weather">{{weather.message??weather.reason}}</p></section><section class="card group-panel"><h2>Discuss and revise</h2><p>Suggest changes here or share this planning-board link in your group chat. Changes to planning inputs invalidate earlier approvals.</p><p v-for="c in board.comments" :key="c.id"><strong>{{c.name}}:</strong> {{c.body}}</p><form @submit.prevent="act(async()=>{await api.meetupComment(id,comment);comment='';})"><label>Message<textarea v-model="comment" maxlength="2000" required /></label><button class="btn btn--primary" :disabled="busy">Post</button></form></section></template></main></template>
